mapper.select:
select t.bp_id as relation_bp_id 
from hls_bp_master t 
where t.bp_code = #{bpCode ,jdbcType=VARCHAR}
and t.bp_name = #{bpName ,jdbcType=VARCHAR}

SELECT br.bp_relation_type, br.description FROM hls_bp_relation br, hls_bp_master bm WHERE bm.bp_class = br.bp_class
AND br.bp_class = #{bpClass}
AND bm.bp_id = #{bpId}
